+fn feeds(path: &Toolpath) -> Vec<crate::geometry::Point3> {
+    path.moves.iter().filter(|m| m.kind == MoveKind::Feed).map(|m| m.to).collect()
+}
+
+fn plunges(path: &Toolpath) -> Vec<crate::geometry::Point3> {
