+    let walled = |_z: f64| -> Result<Option<Region>, GenError> {
+        Ok(Some(Region::new(vec![rect(-20.0, -20.0, 20.0, 20.0)])?.union(&Region::new(vec![rect(20.0, 20.0, 30.0, 40.0)])?)?))
